- *   {@literal @}Inject
- *   public RealPayment(
- *      CreditService creditService,
- *      AuthService authService,
- *      <strong>{@literal @}Assisted Date startDate</strong>,
- *      <strong>{@literal @}Assisted Money amount</strong>) {
- *     ...
