+        HealthIndicatorImpact impact3 = new HealthIndicatorImpact(3, randomAlphaOfLength(20));
+        impacts.add(impact2);
+        impacts.add(impact1);
+        impacts.add(impact3);
+        for (int i = 0; i < 10; i++) {
